package tr.gunplan.app;
import android.app.*;import android.os.*;import android.content.*;import android.net.Uri;import android.provider.Settings;import android.webkit.*;import android.view.*;import android.widget.*;import android.graphics.Color;import org.json.*;import java.io.*;import java.nio.charset.StandardCharsets;
public final class MainActivity extends Activity{
 WebView web;android.widget.FrameLayout root;static final int EXPORT=41,IMPORT=42;int openedTask;
 @Override public void onCreate(Bundle state){super.onCreate(state);android.content.pm.PackageInfo engine=WebView.getCurrentWebViewPackage();int engineVersion=0;try{if(engine!=null)engineVersion=Integer.parseInt(engine.versionName.split("\\.")[0]);}catch(Exception ignored){}if(engineVersion<80){LinearLayout box=new LinearLayout(this);box.setOrientation(LinearLayout.VERTICAL);box.setPadding(36,80,36,36);TextView text=new TextView(this);text.setText(R.string.webview_update_message);text.setTextSize(18);box.addView(text);Button button=new Button(this);button.setText(R.string.webview_update_button);String enginePackage=engine==null?"com.google.android.webview":engine.packageName;button.setOnClickListener(v->{try{startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse("market://details?id="+enginePackage)));}catch(Exception e){Toast.makeText(this,"Uygulama mağazasından Android System WebView / Chrome'u güncelleyin.",Toast.LENGTH_LONG).show();}});box.addView(button);setContentView(box);return;}Reminders.channel(this);openedTask=getIntent().getIntExtra("taskId",0);root=new FrameLayout(this);web=new WebView(this);root.addView(web);setContentView(root);
  root.setOnApplyWindowInsetsListener((v,insets)->{if(Build.VERSION.SDK_INT>=30){android.graphics.Insets bars=insets.getInsets(WindowInsets.Type.systemBars()|WindowInsets.Type.ime());v.setPadding(bars.left,bars.top,bars.right,bars.bottom);}else v.setPadding(insets.getSystemWindowInsetLeft(),insets.getSystemWindowInsetTop(),insets.getSystemWindowInsetRight(),insets.getSystemWindowInsetBottom());return insets;});
  WebSettings w=web.getSettings();w.setJavaScriptEnabled(true);w.setDomStorageEnabled(false);w.setAllowFileAccess(false);w.setAllowContentAccess(false);w.setMixedContentMode(WebSettings.MIXED_CONTENT_NEVER_ALLOW);w.setCacheMode(WebSettings.LOAD_NO_CACHE);web.addJavascriptInterface(new Bridge(),"GunPlan");
  web.setWebViewClient(new WebViewClient(){@Override public WebResourceResponse shouldInterceptRequest(WebView v,WebResourceRequest request){Uri u=request.getUrl();if(!"appassets.androidplatform.net".equals(u.getHost()))return new WebResourceResponse("text/plain","UTF-8",new ByteArrayInputStream(new byte[0]));try{String p=u.getPath();if(p==null||p.equals("/"))p="/index.html";if(!p.matches("/[a-zA-Z0-9._-]+"))throw new IOException();String mime=p.endsWith(".js")?"application/javascript":p.endsWith(".css")?"text/css":p.endsWith(".svg")?"image/svg+xml":"text/html";WebResourceResponse r=new WebResourceResponse(mime,"UTF-8",getAssets().open(p.substring(1)));java.util.Map<String,String> headers=new java.util.HashMap<>();headers.put("Content-Security-Policy","default-src 'self'; script-src 'self'; style-src 'self' 'unsafe-inline'; img-src 'self' data:; connect-src 'none'; object-src 'none'; base-uri 'none'");r.setResponseHeaders(headers);return r;}catch(Exception e){return new WebResourceResponse("text/plain","UTF-8",404,"Not Found",null,new ByteArrayInputStream(new byte[0]));}}
   @Override public boolean shouldOverrideUrlLoading(WebView v,WebResourceRequest r){return !"appassets.androidplatform.net".equals(r.getUrl().getHost());}});
  web.loadUrl("https://appassets.androidplatform.net/index.html");colors();
 }
 @Override protected void onResume(){super.onResume();Reminders.restore(this,false);refresh();}
 @Override protected void onNewIntent(Intent i){super.onNewIntent(i);openedTask=i.getIntExtra("taskId",0);refresh();}
 void refresh(){if(web!=null)web.post(()->web.evaluateJavascript("window.dispatchEvent(new Event('native-refresh'))",null));}
 void message(String text){runOnUiThread(()->{Toast.makeText(this,text,Toast.LENGTH_LONG).show();refresh();});}
 void colors(){if(root==null||web==null)return;try{String theme=TaskStore.read(this).optString("theme","system");boolean dark=theme.equals("dark")||theme.equals("system")&&(getResources().getConfiguration().uiMode&48)==32;int bg=Color.parseColor(dark?"#101B23":"#F5F4EF");root.setBackgroundColor(bg);web.setBackgroundColor(bg);getWindow().setStatusBarColor(bg);getWindow().setNavigationBarColor(Build.VERSION.SDK_INT<27?Color.parseColor("#183F35"):bg);getWindow().getDecorView().setSystemUiVisibility(dark?0:View.SYSTEM_UI_FLAG_LIGHT_STATUS_BAR|View.SYSTEM_UI_FLAG_LIGHT_NAVIGATION_BAR);}catch(Exception ignored){}}
 interface Work{Object run()throws Exception;}
 String reply(Work work){try{return new JSONObject().put("ok",true).put("data",work.run()).toString();}catch(Exception e){try{return new JSONObject().put("ok",false).put("error",e.getMessage()==null?"İşlem tamamlanamadı.":e.getMessage()).toString();}catch(Exception ignored){return "{\"ok\":false,\"error\":\"İşlem tamamlanamadı\"}";}}}
 public final class Bridge{
  @JavascriptInterface public String state(){return reply(()->{JSONObject s=TaskStore.read(MainActivity.this);s.put("notifications",Reminders.allowed(MainActivity.this)).put("exact",Reminders.exact(MainActivity.this)).put("systemDark",(getResources().getConfiguration().uiMode&48)==32).put("openedTask",openedTask);openedTask=0;return s;});}
  @JavascriptInterface public String save(String data){return reply(()->{TaskStore.save(MainActivity.this,data);return true;});}
  @JavascriptInterface public String complete(int id,long occurrence){return reply(()->{TaskStore.complete(MainActivity.this,id,occurrence);return true;});}
  @JavascriptInterface public String toggle(int id){return reply(()->{TaskStore.toggle(MainActivity.this,id);return true;});}
  @JavascriptInterface public String delete(int id){return reply(()->{TaskStore.delete(MainActivity.this,id);return true;});}
  @JavascriptInterface public String theme(String theme){return reply(()->{TaskStore.theme(MainActivity.this,theme);runOnUiThread(()->colors());return true;});}
  @JavascriptInterface public void permission(String kind){runOnUiThread(()->{try{if(kind.equals("notifications")){if(Build.VERSION.SDK_INT>=33&&checkSelfPermission("android.permission.POST_NOTIFICATIONS")!=android.content.pm.PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{"android.permission.POST_NOTIFICATIONS"},9);else startActivity(new Intent(Settings.ACTION_APP_NOTIFICATION_SETTINGS).putExtra(Settings.EXTRA_APP_PACKAGE,getPackageName()));}else if(kind.equals("exact")&&Build.VERSION.SDK_INT>=31)startActivity(new Intent(Settings.ACTION_REQUEST_SCHEDULE_EXACT_ALARM,Uri.parse("package:"+getPackageName())));else if(kind.equals("exact"))message("Bu Android sürümünde ek zaman izni gerekmez.");else if(kind.equals("battery"))startActivity(new Intent(Settings.ACTION_APPLICATION_DETAILS_SETTINGS,Uri.parse("package:"+getPackageName())));}catch(Exception e){message("Telefon ayarlarından GünPlan izinlerini açabilirsiniz.");}});}
  @JavascriptInterface public void test(){runOnUiThread(()->{if(Reminders.allowed(MainActivity.this)){Reminders.test(MainActivity.this);message("Deneme bildirimi gönderildi.");}else message("Önce bildirim iznini açın.");});}
  @JavascriptInterface public void exportData(){runOnUiThread(()->{try{startActivityForResult(new Intent(Intent.ACTION_CREATE_DOCUMENT).setType("application/json").addCategory(Intent.CATEGORY_OPENABLE).putExtra(Intent.EXTRA_TITLE,"GunPlan-Yedek-"+java.time.LocalDate.now()+".json"),EXPORT);}catch(Exception e){message("Dosya seçici açılamadı.");}});}
  @JavascriptInterface public void importData(){runOnUiThread(()->{new AlertDialog.Builder(MainActivity.this).setTitle("Yedekten görev ekle").setMessage("Mevcut kayıtlar korunur. Yedekteki farklı görevler ve geçmiş kayıtlar eklenir; geçmiş tek seferlik görevler yeniden bildirim göndermez.").setNegativeButton("Vazgeç",null).setPositiveButton("Dosya seç",(d,w)->{try{startActivityForResult(new Intent(Intent.ACTION_OPEN_DOCUMENT).setType("*/*").addCategory(Intent.CATEGORY_OPENABLE),IMPORT);}catch(Exception e){message("Dosya seçici açılamadı.");}}).show();});}
 }
 @Override public void onRequestPermissionsResult(int code,String[] perms,int[] results){super.onRequestPermissionsResult(code,perms,results);Reminders.restore(this,false);refresh();}
 @Override protected void onActivityResult(int req,int result,Intent data){super.onActivityResult(req,result,data);if(result!=RESULT_OK||data==null||data.getData()==null)return;Uri uri=data.getData();new Thread(()->{try{if(req==EXPORT){byte[] bytes=TaskStore.read(this).toString(2).getBytes(StandardCharsets.UTF_8);try(OutputStream out=getContentResolver().openOutputStream(uri,"wt")){if(out==null)throw new IOException("Dosya yazılamadı.");out.write(bytes);}message("Yedek kaydedildi.");}else if(req==IMPORT){String text;try(InputStream in=getContentResolver().openInputStream(uri);ByteArrayOutputStream out=new ByteArrayOutputStream()){if(in==null)throw new IOException("Dosya okunamadı.");byte[] b=new byte[4096];int n;while((n=in.read(b))!=-1){out.write(b,0,n);if(out.size()>8000000)throw new IOException("Yedek en fazla 8 MB olabilir.");}text=out.toString("UTF-8");}int count=Backup.merge(this,text);Reminders.restore(this,false);message(count+" görev eklendi. Mevcut kayıtlar korundu.");}}catch(Exception e){message("Yedek işlemi tamamlanamadı: "+e.getMessage());}},"gunplan-backup").start();}
 @Override public void onBackPressed(){if(web==null){super.onBackPressed();return;}web.evaluateJavascript("window.handleBack && window.handleBack()",value->{if(!"true".equals(value))moveTaskToBack(true);});}
 @Override protected void onDestroy(){if(web!=null){web.removeJavascriptInterface("GunPlan");web.destroy();}super.onDestroy();}
}
